 <body>
   <main>
     <section class="contact-card" aria-labelledby="support-title">
       <h1 id="support-title">Contact support</h1>
       <p class="intro">Tell us how to reach you and our support team will follow up as soon as possible.</p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span aria-hidden="true">*</span></label>
           <input
             type="text"
             id="full-name"
             name="fullName"
             autocomplete="name"
             placeholder="Ada Lovelace"
             required
             aria-describedby="full-name-error"
           >
           <p class="error-message" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email">Email address <span aria-hidden="true">*</span></label>
           <input
             type="email"
             id="email"
             name="email"
             autocomplete="email"
             placeholder="ada@example.com"
             required
             aria-describedby="email-error"
           >
           <p class="error-message" id="email-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number <span class="helper-text">(optional)</span></label>
           <input
             type="tel"
             id="phone"
             name="phone"
             autocomplete="tel"
             placeholder="+1 555 123 4567"
             aria-describedby="phone-helper phone-error"
           >
           <p class="helper-text" id="phone-helper">Expected format: optional country code followed by 7 to 15 digits, spaces, hyphens, or parentheses.</p>
           <p class="error-message" id="phone-error" aria-live="polite"></p>
         </div>

         <button type="submit">Submit request</button>
       </form>

       <p class="success-message" id="success-message" role="status">Thanks, your support request is ready to send.</p>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const successMessage = document.querySelector("#success-message");

     const fields = {
       fullName: {
         input: document.querySelector("#full-name"),
         error: document.querySelector("#full-name-error"),
         validate(value) {
           if (!value.trim()) {
             return "Full name is required.";
           }

           if (value.trim().length < 2) {
             return "Full name must be at least 2 characters.";
           }

           return "";
         }
       },
       email: {
         input: document.querySelector("#email"),
         error: document.querySelector("#email-error"),
         validate(value) {
           if (!value.trim()) {
             return "Email address is required.";
           }

           const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
           if (!emailPattern.test(value.trim())) {
             return "Enter a valid email address.";
           }

           return "";
         }
       },
       phone: {
         input: document.querySelector("#phone"),
         error: document.querySelector("#phone-error"),
         validate(value) {
           const trimmedValue = value.trim();
           if (!trimmedValue) {
             return "";
           }

           const phonePattern = /^\+?[\d\s()-]{7,20}$/;
           const digitCount = trimmedValue.replace(/\D/g, "").length;
           if (!phonePattern.test(trimmedValue) || digitCount < 7 || digitCount > 15) {
             return "Enter a phone number with 7 to 15 digits.";
           }

           return "";
         }
       }
     };

     function setFieldError(field, message) {
       field.error.textContent = message;
       field.input.setAttribute("aria-invalid", message ? "true" : "false");
     }

     function validateField(field) {
       const message = field.validate(field.input.value);
       setFieldError(field, message);
       return !message;
     }

     Object.values(fields).forEach((field) => {
       field.input.addEventListener("input", () => {
         validateField(field);
         successMessage.classList.remove("is-visible");
       });

       field.input.addEventListener("blur", () => validateField(field));
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const isValid = Object.values(fields)
         .map(validateField)
         .every(Boolean);
       successMessage.classList.toggle("is-visible", isValid);

       if (isValid) {
         form.reset();
         Object.values(fields).forEach((field) => setFieldError(field, ""));
       }
     });
   </script>
 </body>
 </html>

